version.content:
pipeline {
    agent any

    environment {
        REMOTE_HOST = '20.48.1.68' // 远程服务器地址
        REMOTE_USER = 'root' // 远程服务器用户名
        REMOTE_CREDENTIALS_ID = 'server-18-credentials-id' // 远程服务器SSH凭证ID
        REMOTE_ADDRESS = '/data/soft/kflypt/dataDevelop-gov/test'  // 远程服务器web文件地址
        DIST_PATH = './apps/manage/dist' // 前端软件包产物 manage 包
        TIMESTAMP = new Date().format("yyyyMMddHHmmss", TimeZone.getTimeZone('UTC+8'))
        NODE_VERSION = "v22.13.1" // 定义要使用的Node.js版本
        PNPM_VERSION = "9.15.3" // 定义要使用的pnpm版本
    }

    stages {
        stage('Git') {
            steps {
                echo "Trying to checkout code from gitlab branch: ${params.Branch}"
                checkout scmGit(
                    branches: [[name: "${params.Branch}"]],
                    extensions: [],
                    userRemoteConfigs: [[
                        credentialsId: 'SSH-KEY-FOR-GITLAB',
                        url: '${GIALAB_ADDRESS}/front/PublicDataPlatform/data-development.git'
                    ]]
                )
            }
        }

        stage('Npm Install & Build') {
            steps {
                script {
                    // 使用nvm切换到指定Node.js版本，并安装依赖
                    nvm(NODE_VERSION) {
                        sh '''
                            # 验证Node.js版本
                            node -v

                            # 确保pnpm版本正确（更新或安装指定版本）
                            #if ! pnpm -v | grep -q "${PNPM_VERSION}"; then
                            #    echo "Updating pnpm to ${PNPM_VERSION}..."
                            #    pnpm self-update ${PNPM_VERSION} || npm install -g pnpm@${PNPM_VERSION}
                            #fi

                            # 验证pnpm版本
                            pnpm -v

                            # 打印 Python 2 版本（若存在）
                            echo "Python 2 版本："
                            python --version 2>&1  # 2>&1 确保错误输出也能被捕获（部分系统可能默认指向 Python 3）

                            # 打印 Python 3 版本（推荐，因为多数工具依赖 Python 3）
                            echo "Python 3 版本："
                            python3 --version 2>&1


                            # echo "执行完全清理..."
                            # rm -rf node_modules packages/*/node_modules apps/*/node_modules


                            # ⭐ 关键：删除 lockfile
                            # echo "删除 pnpm-lock.yaml（强制重新生成）"
                            # rm -f pnpm-lock.yaml

                            # echo "=========================================="
                            # echo "2. 重新安装（会根据 ARM64 重新生成 lockfile）"
                            # echo "=========================================="
                            # pnpm install  --no-frozen-lockfile
                            pnpm install --registry=https://registry.npmmirror.com/

                            echo "=========================================="
                            echo "3. 验证 esbuild"
                            echo "=========================================="
                            echo "CPU 架构: $(uname -m)"



                            # 安装项目依赖
                            pnpm install --registry=https://registry.npmmirror.com/

                            export NODE_OPTIONS="--max-old-space-size=4096"
                            pnpm build:test
                        '''
                    }
                }
            }
        }

        stage('Deploy to Remote') {
            steps {
                script {
                    sh 'pwd'
                    // 打包构建结果（假设构建输出到dist-test目录）
                    sh 'tar -zcvf ./dist.tar.gz -C ${DIST_PATH} dist-test'

                    // 上传压缩包到远程服务器
                    sh "scp dist.tar.gz root@${REMOTE_HOST}:${REMOTE_ADDRESS}"

                    // 通过SSH在远程服务器解压并部署
                    sshagent([REMOTE_CREDENTIALS_ID]) {
                        sh """
                            ssh ${REMOTE_USER}@${REMOTE_HOST} '
                                cd ${REMOTE_ADDRESS} &&
                                # 备份旧版本
                                if [ -d "dist-test/" ]; then
                                    mv dist-test/ dist-test-${TIMESTAMP}/
                                fi &&
                                # 解压新包
                                tar -zxvf dist.tar.gz &&
                                # 清理压缩包
                                rm -f dist.tar.gz
                            '
                        """
                    }
                }
            }
        }
    }
}
